693608b9-148f-4666-a4fa-0c47e4f45c63.customCss:
/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ ================= 0. 感谢@薄荷猫宝宝的字体 ================= */
/* 🌟 修复：这里绝对不能加 !important，否则会失效 */
@font-face {
    font-family: 'MasterFont';
    src: url('https://nos.netease.com/ysf/b7a4e983b18dedf08063532c00575aeb.ttf') format('truetype');
}

/* ================= 1. 重置与容器 ================= */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; background: transparent !important; }
.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { display: none !important; width: 0 !important; }

/* 根容器：全透明 */
.xt-root {
    width: 360px !important; 
    height: 700px !important; 
    overflow: hidden !important;
    background-color: transparent !important; 
    background-image: none !important;
    box-shadow: none !important;
    position: relative !important; 
    margin: 20px auto !important;
    display: block !important; 
}

/* 便利贴通用样式 */
.xt-text:nth-of-type(-n+4) {
    position: absolute !important;
    background-color: transparent !important;
    color: #333333 !important;
    font-size: 14px !important;
    line-height: 1.6 !important;
    z-index: 10 !important;
    word-break: break-word !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    box-shadow: none !important;

    /* 🌟 核心：使用@薄荷猫专属字体 */
    font-family: 'MasterFont', sans-serif !important;
}

/* 胶带通用样式 */
.xt-text:nth-of-type(-n+4)::before {
    content: '' !important;
    position: absolute !important;
    top: -0px !important;
    left: 50% !important;
    transform: translateX(-50%) rotate(-3deg) !important;
    width: 55px !important;
    height: 18px !important;
    background-color: rgba(255, 255, 255, 0.5) !important;
    backdrop-filter: blur(1px) !important;
    -webkit-backdrop-filter: blur(1px) !important;
    border-left: 1px dashed rgba(0,0,0,0.05) !important;
    border-right: 1px dashed rgba(0,0,0,0.05) !important;
    z-index: 11 !important;
}

/* 🌟 便利贴 1 */
.xt-text:nth-of-type(1) {
    background-image: url('https://i.postimg.cc/CxcWCpCz/IMG-6514.jpg') !important;
    top: 40px !important;
    left: 25px !important;
    width: 200px !important;
    height: 180px !important;
    transform: rotate(-6deg) !important;
    padding: 35px 20px 20px 30px !important;
}

/* 🌟 便利贴 2 */
.xt-text:nth-of-type(2) {
    background-image: url('https://i.postimg.cc/9fzsJg1Q/IMG-6515.jpg') !important;
    top: 185px !important;
    left: 145px !important;
    width: 190px !important;
    height: 170px !important;
    transform: rotate(5deg) !important;
    padding: 30px 20px 20px 25px !important;
}

/* 🌟 便利贴 3 */
.xt-text:nth-of-type(3) {
    background-image: url('https://i.postimg.cc/JhtSPYKn/IMG-6517.jpg') !important;
    top: 320px !important;
    left: 20px !important;
    width: 190px !important;
    height: 170px !important;
    transform: rotate(-3deg) !important;
    padding: 35px 20px 20px 25px !important;
}

/* 🌟 便利贴 4 */
.xt-text:nth-of-type(4) {
    background-image: url('https://i.postimg.cc/VN52DZ45/IMG-6516.jpg') !important;
    top: 460px !important;
    left: 145px !important;
    width: 185px !important;
    height: 165px !important;
    transform: rotate(4deg) !important;
    padding: 30px 20px 20px 25px !important;
}

/* ================= 2. 贴纸部分 (绝对不遮挡，z-index: 20) ================= */

/* 🌸 贴纸 1 */
.xt-text:nth-of-type(1)::after {
    content: '' !important;
    position: absolute !important;
    background-image: url('https://i.postimg.cc/134bmY6s/IMG-6547.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    z-index: 99999 !important; 
    pointer-events: none !important;
    width: 60px !important;  
    height: 60px !important; 
    top: 510px !important;    
    left: 40px !important;  
    transform: rotate(5deg) !important; 
}

/* 🌸 贴纸 2 */
.xt-text:nth-of-type(2)::after {
    content: '' !important;
    position: absolute !important;
    background-image: url('https://i.postimg.cc/jj40Wn8P/IMG-6531.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    z-index: 20 !important;
    pointer-events: none !important;
    width: 55px !important;
    height: 55px !important;
    top: -40px !important;
    left: 130px !important;
    transform: rotate(10deg) !important;
}

/* 🌸 贴纸 3 */
.xt-text:nth-of-type(3)::after {
    content: '' !important;
    position: absolute !important;
    background-image: url('https://i.postimg.cc/6pTFW1R9/IMG-6544.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    z-index: 20 !important;
    pointer-events: none !important;
    width: 50px !important;
    height: 30px !important;
    top: -280px !important;
    left: 90px !important;
    transform: rotate(-5deg) !important;
}

/* 🌸 贴纸 4 */
.xt-text:nth-of-type(4)::after {
    content: '' !important;
    position: absolute !important;
    background-image: url('https://i.postimg.cc/KYDSK39L/IMG-6533.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    z-index: 20 !important;
    pointer-events: none !important;
    width: 100px !important;
    height: 100px !important;
    top: 110px !important;
    left: -60px !important;
    transform: rotate(-3deg) !important;
}

